/**
 * lay
 * 基础模块
 */

import { log } from './logger.js';

const { document } = window;
const lay = Object.create(null);
const version = '__VERSION__';

const fnToString = Function.prototype.toString;
const ObjectFunctionString = fnToString.call(Object);
const hasOwnProperty = Object.prototype.hasOwnProperty;

/**
 * 使用入口
 *
 * 保留 `layui.use` 作为「开始使用」的语义，用于确保组件实例化的执行时序。
 * 但当前不再承载模块加载或依赖解析的职责，模块体系已全面迁移至 ES Modules。
 * 我们希望它依然是一个具有高辨别度的门户、一个具有特殊意蕴的连接。
 *
 * @param {Function} callback - DOM 就绪后执行的回调函数
 */
const use = (lay.use = (callback) => {
  if (document.readyState === 'loading') {
    document.addEventListener(
      'DOMContentLoaded',
      () => {
        queueMicrotask(callback);
      },
      { once: true },
    );
  } else {
    queueMicrotask(callback);
  }
});

/**
 * 将一个或多个对象合并到目标对象中
 * 对象类型值始终进行「深拷贝」合并。若需浅拷贝合并，请使用 Object.assign()
 * @param {*} target - 目标对象
 * @param {...*} objectN - 一个或多个包含要应用的属性的源对象
 * @param {Function} customizer - 可选的自定义合并函数
 * @returns {*} 返回合并后的对象
 * @example
 *```js
 * console.log(lay.extend({}, {a:1})); // expected: {a:1}
 * console.log(lay.extend({a:1}, {a:3}, {a:5,b:5})); // expected: {a:5,b:5}
 * // 多个相同源对象的不同合并方式
 * const objN = [
 *   {
 *     a: [1, 3],
 *     b: {ba: 1}
 *   },
 *   {
 *     a: [5],
 *     b: {bb: 2}
 *   },
 *   {
 *     b: {ba: 3},
 *     c: 3
 *   }
 * ];
 * console.log(lay.extend({}, ...objN)); // expected: {a:[5,3],b:{ba:3,bb:2},c:3}
 * // 使用 customizer 实现数组覆盖而非合并
 * const obj1 = lay.extend({}, ...objN, function(objValue, srcValue) {
 *   if (Array.isArray(objValue) && Array.isArray(srcValue)) {
 *     return srcValue;
 *   }
 * });
 * console.log(obj1); // expected: {a:[5],b:{ba:3,bb:2},c:3}
 * // 使用 customizer 实现特定字段跳过合并
 * const obj2 = lay.extend({}, ...objN, function(objValue, srcValue, key, target, source) {
 *   if (key === 'b') {
 *     return objValue;
 *   }
 * });
 * console.log(obj2); // expected: {a:[5,3],b:{ba:1},c:3}
 * ```
 */
lay.extend = function () {
  var args = [].slice.call(arguments);

  // 最后一个参数是否为 customizer
  var customizer =
    typeof args[args.length - 1] === 'function' ? args.pop() : false;

  // 深拷贝合并
  return args.reduce(function (target, source) {
    // 确保 target 始终是一个对象
    if (typeof target !== 'object' || target === null) {
      target = {};
    }

    for (var key in source) {
      if (!hasOwnProperty.call(source, key)) continue; // 仅处理自有属性

      var targetValue = target[key];
      var sourceValue = source[key];

      // 自定义合并逻辑（如数组覆盖、特定字段跳过等）
      if (customizer) {
        var customResult = customizer(
          targetValue,
          sourceValue,
          key,
          target,
          source,
        );
        if (customResult !== undefined) {
          target[key] = customResult;
          continue;
        }
      }

      // 默认深拷贝逻辑
      if (Array.isArray(sourceValue)) {
        targetValue = Array.isArray(targetValue) ? targetValue : [];
      } else if (lay.isPlainObject(sourceValue)) {
        targetValue = lay.isPlainObject(targetValue) ? targetValue : {};
      }
      target[key] =
        lay.isPlainObject(sourceValue) || Array.isArray(sourceValue)
          ? lay.extend(targetValue, sourceValue, customizer)
          : sourceValue;
    }

    return target;
  });
};

/**
 * 判断是否为纯对象
 * @param {*} obj - 要检查的对象
 * @returns {boolean}
 */
lay.isPlainObject = function (obj) {
  if (
    obj === null ||
    typeof obj !== 'object' ||
    Object.prototype.toString.call(obj) !== '[object Object]'
  ) {
    return false;
  }

  var proto = Object.getPrototypeOf(obj);

  // Object.create(null) 创建的对象
  if (proto === null) {
    return true;
  }

  // 判定具有原型且由全局 Object 构造函数创建的对象为纯对象（来自 jQuery 方案）
  var Ctor = hasOwnProperty.call(proto, 'constructor') && proto.constructor;
  return (
    typeof Ctor === 'function' && fnToString.call(Ctor) === ObjectFunctionString
  );
};

/**
 * typeof 类型细分 -> string/number/boolean/undefined/null、object/array/function/…
 * @param {*} operand - 任意值
 * @returns {string}
 */
lay.type = function (operand) {
  if (operand === null) return String(operand);

  // 细分引用类型
  return typeof operand === 'object' || typeof operand === 'function'
    ? (function () {
        var type =
          Object.prototype.toString.call(operand).match(/\s(.+)\]$/) || []; // 匹配类型字符
        var classType = 'Function|Array|Date|RegExp|Object|Error|Symbol'; // 常见类型字符

        type = type[1] || 'Object';

        // 除匹配到的类型外，其他对象均返回 object
        return new RegExp('\\b(' + classType + ')\\b').test(type)
          ? type.toLowerCase()
          : 'object';
      })()
    : typeof operand;
};

/**
 * 对象是否具备「类数组」结构（此处为兼容 jQuery 对象）
 * @param {Object} obj - 任意对象
 * @returns {boolean}
 */
lay.isArray = function (obj) {
  var len;
  var type = lay.type(obj);

  if (!obj || typeof obj !== 'object' || obj === window) return false;

  len = 'length' in obj && obj.length;
  return (
    type === 'array' ||
    len === 0 ||
    (typeof len === 'number' && len > 0 && len - 1 in obj) // 兼容 jQuery 对象
  );
};

/**
 * 本地存储
 * @param {string} table - 表名
 * @param {Object} settings - 设置项
 * @param {Storage} storage - 存储对象，localStorage | sessionStorage
 * @returns {Object}
 */
lay.storage = function (table = 'LAY', settings, storage) {
  storage = storage || localStorage;

  // 如果 settings 为 null，则删除表
  if (settings === null) {
    return delete storage[table];
  }

  settings = typeof settings === 'object' ? settings : { key: settings };

  var data;

  try {
    data = JSON.parse(storage[table]);
  } catch {
    data = {};
  }

  if ('value' in settings) {
    data[settings.key] = settings.value;
  }
  if (settings.remove) {
    delete data[settings.key];
  }

  storage[table] = JSON.stringify(data);

  return settings.key ? data[settings.key] : data;
};

/**
 * 本地会话存储
 * @param {string} table - 表名
 * @param {Object} settings - 设置项
 * @returns {Object}
 */
lay.sessionStorage = function (table, settings) {
  return lay.storage(table, settings, sessionStorage);
};

/**
 * 设备信息
 * @param {string} key - 任意 key
 * @returns {Object}
 */
lay.device = function (key) {
  var agent = navigator.userAgent.toLowerCase();

  // 获取版本号
  var getVersion = function (label) {
    var exp = new RegExp(label + '/([^\\s\\_\\-]+)');
    label = (agent.match(exp) || [])[1];
    return label || false;
  };

  // 返回结果集
  var result = {
    os: (function () {
      // 底层操作系统
      if (/windows/.test(agent)) {
        return 'windows';
      } else if (/linux/.test(agent)) {
        return 'linux';
      } else if (/iphone|ipod|ipad|ios/.test(agent)) {
        return 'ios';
      } else if (/mac/.test(agent)) {
        return 'mac';
      }
    })(),
    weixin: getVersion('micromessenger'), // 是否微信
  };

  // 任意的 key
  if (key && !result[key]) {
    result[key] = getVersion(key);
  }

  // 移动设备
  result.android = /android/.test(agent);
  result.ios = result.os === 'ios';
  result.mobile = result.android || result.ios;

  return result;
};

/**
 * IE 版本
 * @type {string | boolean} - 如果是 IE 返回版本字符串，否则返回 false
 */
lay.ie = (function () {
  var agent = navigator.userAgent.toLowerCase();
  return !!window.ActiveXObject || 'ActiveXObject' in window
    ? (agent.match(/msie\s(\d+)/) || [])[1] || '11' // 由于 ie11 并没有 msie 的标识
    : false;
})();

/**
 * 将数组中的成员对象按照某个 key 的 value 值进行排序
 * @param {Object[]} arr - 任意数组
 * @param {string} key - 任意 key
 * @param {boolean} desc - 是否降序
 * @param {boolean} notClone - 是否不对 arr 进行克隆
 * @returns {Object[]}
 */
lay.sort = function (arr, key, desc, notClone) {
  var clone = notClone ? arr || [] : JSON.parse(JSON.stringify(arr || []));

  // 若未传入 key，则直接返回原对象
  if (lay.type(arr) === 'object' && !key) {
    return clone;
  } else if (typeof arr !== 'object') {
    // 若 arr 非对象
    return [clone];
  }

  // 开始排序
  clone.sort(function (o1, o2) {
    var v1 = o1[key];
    var v2 = o2[key];

    /*
     * 特殊数据
     * 若比较的成员均非对象
     */

    // 若比较的成员均为数字
    if (!isNaN(o1) && !isNaN(o2)) return o1 - o2;

    // 若比较的成员只存在某一个非对象
    if (!isNaN(o1) && isNaN(o2)) {
      if (key && typeof o2 === 'object') {
        v1 = o1;
      } else {
        return -1;
      }
    } else if (isNaN(o1) && !isNaN(o2)) {
      if (key && typeof o1 === 'object') {
        v2 = o2;
      } else {
        return 1;
      }
    }

    /*
     * 正常数据
     * 即成员均为对象，也传入了对比依据： key
     * 若 value 为数字，按「大小」排序；若 value 非数字，则按「字典序」排序
     */

    // value 是否为数字
    var isNum = [!isNaN(v1), !isNaN(v2)];

    // 若为数字比较
    if (isNum[0] && isNum[1]) {
      if (v1 && !v2 && v2 !== 0) {
        // 数字 vs 空
        return 1;
      } else if (!v1 && v1 !== 0 && v2) {
        // 空 vs 数字
        return -1;
      } else {
        // 数字 vs 数字
        return v1 - v2;
      }
    }

    /**
     * 字典序排序
     */

    // 若为非数字比较
    if (!isNum[0] && !isNum[1]) {
      // 字典序比较
      if (v1 > v2) {
        return 1;
      } else if (v1 < v2) {
        return -1;
      } else {
        return 0;
      }
    }

    // 若为混合比较
    if (isNum[0] || !isNum[1]) {
      // 数字 vs 非数字
      return -1;
    } else if (!isNum[0] || isNum[1]) {
      // 非数字 vs 数字
      return 1;
    }
  });

  desc && clone.reverse(); // 倒序
  return clone;
};

// 移除事件的特殊标识
var EV_REMOVE = 'LAY-EVENT-REMOVE';

// 事件缓存集
lay.events = {};

/**
 * 自定义模块事件
 * @param {string} modName - 模块名
 * @param {string} events - 事件名
 * @param {Function} callback - 回调
 * @returns {Object}
 */
lay.onevent = function (modName, events, callback) {
  if (typeof modName !== 'string' || typeof callback !== 'function') {
    return this;
  }
  return lay.event(modName, events, null, callback);
};

/**
 * 执行自定义模块事件
 * @param {string} modName - 模块名
 * @param {string} events - 事件名
 * @param {Object} params - 参数
 * @param {Function} fn - 回调
 */
lay.event = function (modName, events, params, fn) {
  var result = null;
  var filter = (events || '').match(/\((.*)\)$/) || []; // 提取事件过滤器字符结构，如：select(xxx)
  var eventName = (modName + '.' + events).replace(filter[0], ''); // 获取事件名称，如：form.select
  var filterName = filter[1] || ''; // 获取过滤器名称, 如：xxx
  var callback = (item) => {
    var res = item && item.call(this, params);
    res === false && result === null && (result = false);
  };

  // 如果参数传入特定字符，则执行移除事件
  if (params === EV_REMOVE) {
    delete (lay.events[eventName] || {})[filterName];
    return lay;
  }

  // 添加事件
  if (fn) {
    lay.events[eventName] = lay.events[eventName] || {};

    if (filterName) {
      // 带 filter 不支持重复事件
      lay.events[eventName][filterName] = [fn];
    } else {
      // 不带 filter 处理的是所有的同类事件，应该支持重复事件
      lay.events[eventName][filterName] =
        lay.events[eventName][filterName] || [];
      lay.events[eventName][filterName].push(fn);
    }
    return this;
  }

  // 执行事件回调
  const eventHandlers = lay.events[eventName];
  for (const key in eventHandlers) {
    const item = eventHandlers[key];

    // 执行当前模块的全部事件
    if (filterName === '{*}') {
      item.forEach(callback);
      continue;
    }

    // 执行指定事件
    key === '' && item.forEach(callback);
    filterName && key === filterName && item.forEach(callback);
  }

  return result;
};

/**
 * 新增模块事件
 * @param {string} events - 事件名
 * @param {string} modName - 模块名
 * @param {Function} callback - 回调
 * @returns {Object}
 */
lay.on = function (events, modName, callback) {
  return lay.onevent(modName, events, callback);
};

/**
 * 移除模块事件
 * @param {string} events - 事件名
 * @param {string} modName - 模块名
 * @returns {Object}
 */
lay.off = function (events, modName) {
  return lay.event(modName, events, EV_REMOVE);
};

/**
 * 防抖
 * @param {Function} func - 回调
 * @param {number} wait - 延时执行的毫秒数
 * @returns {Function}
 */
lay.debounce = function (func, wait) {
  var timeout;
  return function () {
    var context = this;
    var args = arguments;
    clearTimeout(timeout);
    timeout = setTimeout(function () {
      func.apply(context, args);
    }, wait);
  };
};

/**
 * 节流
 * @param {Function} func - 回调
 * @param {number} wait - 不重复执行的毫秒数
 */
lay.throttle = function (func, wait) {
  var cooldown = false;
  return function () {
    var context = this;
    var args = arguments;
    if (!cooldown) {
      func.apply(context, args);
      cooldown = true;
      setTimeout(function () {
        cooldown = false;
      }, wait);
    }
  };
};

/**
 * 数字前置补零
 * @param {number | string} num - 原始数字
 * @param {number} [length=2] - 数字长度，如果原始数字长度小于 length，则前面补零
 * @returns {string} 返回补 0 后的数字
 * @example
 * ```js
 * lay.digit(6, 2); // "06"
 * lay.digit('7', 3); // "007"
 * ```
 */
lay.digit = function (num, length) {
  if (!(typeof num === 'string' || typeof num === 'number')) return '';

  var str = '';
  num = String(num);
  length = length || 2;
  for (var i = num.length; i < length; i++) {
    str += '0';
  }
  return num < Math.pow(10, length) ? str + num : num;
};

/**
 * 获取单个 DOM 元素
 * @param {string | HTMLElement | JQuery} elem - 目标元素或选择器
 * @returns {HTMLElement | null}
 */
var getElement = function (elem) {
  if (!elem) return null;
  if (typeof elem === 'string') {
    return document.querySelector(elem);
  }
  if (elem.jquery || typeof elem.length === 'number') {
    return elem[0] || null;
  }
  return elem;
};

/**
 * 创建元素
 * @param {string} elemName - 元素的标签名
 * @param {Object.<string, string>} [attr] - 添加到元素上的属性
 * @returns {HTMLElement} 返回创建的 HTML 元素
 * @example
 * ```js
 * // <div id="test"></div>
 * lay.createElement('div', {
 *  id: 'test'
 * })
 * ```
 */
lay.createElement = function (elemName, attr) {
  var elem = document.createElement(elemName);

  for (const [key, value] of Object.entries(attr || {})) {
    elem.setAttribute(key, value);
  }

  return elem;
};

/**
 * 当前页面是否存在滚动条
 * @returns {boolean} 是否存在滚动条
 * @example
 * ```
 * lay.hasScrollbar() // true 或 false
 * ```
 */
lay.hasScrollbar = function () {
  return (
    document.body.scrollHeight >
    (window.innerHeight || document.documentElement.clientHeight)
  );
};

/**
 * 自动递增器，一般用于组件自增索引
 */
lay.autoIncrementer = function (key, opts = {}) {
  const { target = document.body } = opts;
  const name = '_LAY_AUTOINCREMENTER_ID_';
  const incrementer = (target[name] = target[name] || {});

  incrementer[key] = incrementer[key] || 0;
  return ++incrementer[key];
};

/**
 * 获取节点的 style 属性值
 * @param {HTMLElement} node - 节点
 * @param {string} name - 属性名
 * @returns 属性值
 */
lay.getStyle = function (node, name) {
  var style = window.getComputedStyle(node, null);
  return style.getPropertyValue(name);
};

/**
 * 获取 style rules
 * @param {HTMLStyleElement} style - HTMLStyle 元素
 * @param {(ruleItem: CSSStyleRule, index: number) => boolean} [callback] - 用来返回 style 元素中的每个 `style rule` 的函数，返回 true 终止遍历
 * @returns {CSSRuleList} 返回 `style rules`
 * @example
 * ```
 * <style id="test">
 *   .lay-card{
 *     color: #000;
 *   }
 *   .lay-btn-success{
 *     color: green;
 *   }
 * </style>
 *
 * lay.getStyleRules($('#test')[0], function(rule, index){
 *   if(rule.selectorText === '.lay-card'){
 *     console.log(index, rule.cssText) // 0 '.lay-card{color: #000}'
 *     rule.style.color = '#EEE';
 *     return true; // 终止遍历
 *   }
 * }) // RuleList
 * ```
 */
lay.getStyleRules = function (style, callback) {
  if (!style) return;

  var sheet = style.sheet || {};
  var rules = sheet.cssRules || [];

  if (typeof callback === 'function') {
    for (const [index, item] of Array.from(rules).entries()) {
      if (callback(item, index)) {
        break;
      }
    }
  }

  return rules;
};

/**
 * 创建 style 样式
 * @param {Object} options - 可配置的选项
 * @param {string | HTMLElement | JQuery} [options.target] - 目标容器，指定后会将样式追加到目标容器
 * @param {string} [options.id] - 样式元素的 id，默认自增
 * @param {string} options.text - 样式内容
 * @returns {HTMLStyleElement} 返回创建的样式元素
 * @example
 * ```html
 * <div id="targetEl">
 *   <!-- 样式追加到目标容器 -->
 *   <style id="LAY-STYLE-DF-0">.card{color: #000}</style>
 * </div>
 *
 * lay.style({
 *   target: '#targetEl',
 *   text: '.card{color: #000}'
 * }) // <style id="LAY-STYLE-DF-0">.card{color: #000}</style>
 * ```
 */
lay.style = function (options) {
  options = options || {};

  var style = lay.createElement('style');
  var styleText = options.text || '';
  var target = options.target;

  if (!styleText) return;

  // 添加样式
  style.innerHTML = styleText;

  // ID
  style.id =
    'LAY-STYLE-' +
    (options.id ||
      (function (index) {
        lay.style.index = ++index;
        return 'DF-' + index;
      })(lay.style.index || 0));

  // 是否向目标容器中追加 style 元素
  if (target) {
    var targetElem = getElement(target);
    if (!targetElem) return style;

    var styleElem = targetElem.querySelector('#' + style.id);
    styleElem?.remove();
    targetElem.appendChild(style);
  }

  return style;
};

/**
 * 将元素定位到指定目标元素附近
 * @param {HTMLElement} target - 目标元素
 * @param {HTMLElement} elem - 定位元素
 * @param {Object} [opts] - 可配置的选项
 * @param {'absolute' | 'fixed'} [opts.position] - 元素的定位类型
 * @param {'left' | 'right'} [opts.clickType="left"] - 点击类型，默认为 'left'，如果 {@link target} 是 document 或 body 元素，则为 'right'
 * @param {'left' | 'right' | 'center'} [opts.align="left"] - 对齐方式
 * @param {boolean} [opts.allowBottomOut=false] - 顶部没有足够区域显示时，是否允许底部溢出
 * @param {number} [opts.gap=5] - 与目标元素的间距（px）
 * @param {Event} [opts.e] - 事件对象，仅右键生效
 * @param {boolean} [opts.SYSTEM_RELOAD] - 是否重载，用于出现滚动条时重新计算位置
 * @param {[offsetX:number, offsetY:number]} [opts.offset] - 相对于触发元素的额外偏移量[x,y]
 * @example
 * ```js
 * <button id="targetEl">dropdown</button>
 * <ul id="contentEl" class="dropdown-menu">
 *   <li>菜单1</li>
 *   <li>菜单2</li>
 * </ul>
 *
 * // 下拉菜单将被定位到按钮附近
 * lay.position(
 *   $('#targetEl')[0],
 *   $('#contentEl')[0],
 *   {
 *     position: 'fixed',
 *     align: 'center'
 *   }
 * )
 * ```
 */
lay.position = function (target, elem, opts) {
  if (!elem) return;
  opts = opts || {};

  // 如果绑定的是 document 或 body 元素，则直接获取鼠标坐标
  if (target === document || target === document.body) {
    opts.clickType = 'right';
  }

  // 绑定绑定元素的坐标
  var rect =
    opts.clickType === 'right'
      ? (function () {
          var e = opts.e || window.event || {};
          return {
            left: e.clientX,
            top: e.clientY,
            right: e.clientX,
            bottom: e.clientY,
          };
        })()
      : target.getBoundingClientRect();
  var elemWidth = elem.offsetWidth; // 控件的宽度
  var elemHeight = elem.offsetHeight; // 控件的高度

  // 滚动条高度
  var scrollArea = function (type) {
    type = type ? 'scrollLeft' : 'scrollTop';
    return document.body[type] | document.documentElement[type];
  };

  // 窗口宽高
  var winArea = function (type) {
    return document.documentElement[type ? 'clientWidth' : 'clientHeight'];
  };
  var gap = 'gap' in opts ? opts.gap : 5;
  var left = rect.left;
  var top = rect.bottom;

  // 相对元素居中
  if (opts.align === 'center') {
    left = left - (elemWidth - target.offsetWidth) / 2;
  } else if (opts.align === 'right') {
    left = left - elemWidth + target.offsetWidth;
  }

  // 判断右侧是否超出边界
  if (left + elemWidth + gap > winArea('width')) {
    left = winArea('width') - elemWidth - gap; // 如果超出右侧，则将面板向右靠齐
  }
  // 左侧是否超出边界
  if (left < gap) left = gap;

  // 判断底部和顶部是否超出边界
  if (rect.bottom + elemHeight + gap > winArea()) {
    // 底部超出边界
    // 优先判断顶部是否有足够区域显示完全，且底部不能超出边界
    if (rect.top > elemHeight + gap && rect.top <= winArea()) {
      top = rect.top - elemHeight - gap * 2; // 顶部有足够的区域显示
    } else if (!opts.allowBottomOut) {
      // 顶部没有足够区域显示时，是否允许底部溢出
      top = winArea() - elemHeight - gap * 2; // 面板向底部靠齐
      if (top < 0) top = 0; // 如果面板底部靠齐时，又溢出窗口顶部，则只能将顶部靠齐
    }
  }
  /*
  if (top + elemHeight + gap > winArea()) {
    // 优先顶部是否有足够区域显示完全
    if (rect.top > elemHeight + gap) {
      top = rect.top - elemHeight - gap * 2; // 顶部有足够的区域显示
    } else {
      // 如果面板是鼠标右键弹出，且顶部没有足够区域显示，则将面板向底部靠齐
      if (obj.clickType === 'right') {
        top = winArea() - elemHeight - gap * 2;
        if (top < 0) top = 0; // 不能溢出窗口顶部
      } else {
        top = gap; // 位置计算逻辑完备性处理
      }
    }
  } */

  // 定位类型
  var position = opts.position;
  if (position) elem.style.position = position;
  var offsetX = opts.offset ? opts.offset[0] : 0;
  var offsetY = opts.offset ? opts.offset[1] : 0;

  // 设置坐标
  elem.style.left =
    left + (position === 'fixed' ? 0 : scrollArea(1)) + offsetX + 'px';
  elem.style.top =
    top + (position === 'fixed' ? 0 : scrollArea()) + offsetY + 'px';

  // 防止页面无滚动条时，又因为弹出面板而出现滚动条导致的坐标计算偏差
  if (!lay.hasScrollbar()) {
    var rect1 = elem.getBoundingClientRect();
    // 如果弹出面板的溢出窗口底部，则表示将出现滚动条，此时需要重新计算坐标
    if (!opts.SYSTEM_RELOAD && rect1.bottom + gap > winArea()) {
      opts.SYSTEM_RELOAD = true;
      setTimeout(function () {
        lay.position(target, elem, opts);
      }, 50);
    }
  }
};

/**
 * 获取元素上的属性配置项
 *
 * @deprecated 鉴于 CSP 策略，该方法已弃用。
 * 将统一使用 dataset 方案获取元素上的 `data-*` 配置信息。
 * 因当前 table 组件仍有依赖，该方法暂不移除，待 table 重写完成后将正式移除。
 *
 * @param {string | HTMLElement | JQuery} elem - HTML 元素
 * @param {{attr: string} | string} [opts="lay-options"] - 可配置的选项，string 类型指定属性名
 * @returns {Object.<string, any>} 返回元素上的属性配置项
 * @example
 * ```js
 * <div id="testEl" lay-options="{color:red}" lay-toc="{hot: true}"></div>
 *
 * var elem = $('#testEl')
 * lay.options(elem) // {color:red}
 * lay.options(elem[0]) // {color:red}
 * lay.options('#testEl') // {color:red}
 * lay.options('#testEl', {attr: 'lay-toc'}) // {hot: true}
 * lay.options('#testEl', 'lay-toc') // {hot: true}
 *
 * $('#testEl').attr('lay-toc') // '{hot: true}'
 * ```
 */
lay.options = function (elem, opts) {
  opts = typeof opts === 'object' ? opts : { attr: opts };

  if (elem === document) return {};

  var attrName = opts.attr || 'lay-options';
  var targetElem = getElement(elem);
  var attrValue = targetElem ? targetElem.getAttribute(attrName) : null;

  try {
    /**
     * 请注意: 开发者在使用 lay-options="{}" 配置组件选项时，需确保属性值不来自于网页用户,
     * 即属性值必须在网页开发者自身的可控范围内，否则请勿在 HTML 标签属性中获取组件选项。
     */
    return new Function('return ' + (attrValue || '{}'))();
  } catch (ev) {
    log(
      opts.errorText ||
        [attrName + '="' + attrValue + '"', '\n parseerror: ' + ev].join('\n'),
      'error',
    );
    return {};
  }
};

/**
 * 解析元素 dataset 上的配置信息
 * @param {string | HTMLElement | JQuery} elem - 目标元素
 * @param {Object} [opts] - 配置对象
 * @param {string} [opts.prefix='lay'] - 约定读取的 dataset 前缀；
 *  默认只解析 `data-lay-*` 属性；若要解析所有 `data-*` 属性，可将 prefix 设置为 `''`
 * @param {string} [opts.connector='.'] - 嵌套属性的连接符
 * @param {Function} [opts.beforeParseValue] - 值类型转换前的回调；
 *  接收 {rawKey: string, rawValue: string} 参数；返回 false 则不转换
 * @returns {Object} 返回 options 对象
 * @example
 * ```html
 * <div id="testEl"
 *   data-lay-size="xl"
 *   data-lay-index="0"
 *   data-lay-default-open="true"
 *   data-lay-colors='["red", "green", "blue"]'
 *   data-lay-tree.flag="null"
 * ></div>
 * ```
 * ```js
 * const datasetOptions = lay.parseDataset('#testEl');
 * console.log(datasetOptions);
 * // {
 * //   size: 'xl',
 * //   index: 0,
 * //   defaultOpen: true,
 * //   colors: ['red', 'green', 'blue'],
 * //   tree: {
 * //     flag: null
 * //   }
 * // }
 * ```
 */
lay.parseDataset = function (elem, opts) {
  const targetElem = getElement(elem);
  const dataset = targetElem?.dataset;

  if (!dataset) return {};

  opts = {
    prefix: 'lay',
    connector: '.',
    // beforeParseValue: null,
    ...opts,
  };

  // 根据 JSON 规范进行值类型转换
  // 如：`"true"` -> `true`, `"123"` -> `123`, `"[1,2,3]"` -> `[1,2,3]`
  const parseValue = ({ rawKey, rawValue }) => {
    // 值类型转换前的回调；返回 false 则不转换
    const beforeParseResult = opts.beforeParseValue?.({
      rawKey,
      rawValue,
    });

    if (beforeParseResult === false || !rawValue.trim()) {
      return rawValue;
    }

    try {
      return JSON.parse(rawValue);
    } catch {
      return rawValue;
    }
  };

  // 嵌套解析
  const parseNested = (target, rawKey, rawValue) => {
    const keys = rawKey.split(opts.connector).filter(Boolean);
    if (!keys.length) return;

    let current = target;
    const value = parseValue({ rawKey, rawValue });

    // 逐级创建选项
    for (const [index, key] of keys.entries()) {
      // 最后一级直接赋值
      if (index === keys.length - 1) {
        // 若目标位置已存在对象值（如先由嵌套属性创建），覆盖前打印提示
        if (lay.isPlainObject(current[key])) {
          log(
            `parseDataset: Property "data-${rawKey}" overwrites the existing object at "data-${keys
              .slice(0, index + 1)
              .join(opts.connector)}"`,
          );
        }
        current[key] = value;
        continue;
      }

      // 初始化父级对象
      if (!lay.hasOwn(current, key)) {
        current[key] = {};
      } else if (!lay.isPlainObject(current[key])) {
        // 若父级已存在非对象值，则视为无效嵌套
        log(
          `parseDataset: Cannot set nested property "data-${rawKey}" on non-object value at "data-${keys
            .slice(0, index + 1)
            .join(opts.connector)}"`,
        );
        return;
      }

      current = current[key];
    }
  };

  // 获取特定前缀后的属性 Key
  const getKey = (rawKey) => {
    // 无任何前缀，即表示读取 `data-*` 配置信息
    if (!opts.prefix) {
      return rawKey;
    }

    const key = rawKey.slice(opts.prefix.length);

    // 若移除前缀后的属性名不以大写字母开头，则视为无效属性
    // 该逻辑为避免匹配到 data-lay* ，有效的属性名应为 data-lay-*
    if (!rawKey.startsWith(opts.prefix) || !/^[A-Z]/.test(key)) {
      return '';
    }

    return key.charAt(0).toLowerCase() + key.slice(1);
  };

  const dataOptions = {};

  Object.entries(dataset).forEach(([rawKey, rawValue]) => {
    const key = getKey(rawKey);

    if (key) {
      parseNested(dataOptions, key, rawValue);
    }
  });

  return dataOptions;
};

/**
 * 元素是否属于顶级元素（document 或 body）
 * @param {HTMLElement} elem - HTML 元素
 * @returns {boolean} 是否属于顶级元素
 * @example
 * ```js
 * lay.isTopElem(document) // true
 * ```
 */
lay.isTopElem = function (elem) {
  const topElems = [document, document.body];
  let matched = false;

  for (const item of topElems) {
    if (item === elem) {
      matched = true;
      break;
    }
  }

  return matched;
};

// 剪切板
lay.clipboard = {
  /**
   * 写入文本
   * @param {Object} options - 可配置的选项
   * @param {string} options.text - 写入剪贴板的文本
   * @param {() => void} [options.done] - 写入成功/完成回调
   * @param {(err?: any) => void} [options.error] - 写入失败回调
   * @example
   * ```js
   * lay.clipboard.writeText({
   *   text: '测试文本',
   *   done: function(){ layer.msg('copied')},
   *   error: function(){ layer.msg('error')}
   * })
   * ```
   */
  writeText: function (options) {
    var text = String(options.text);

    if (navigator && 'clipboard' in navigator) {
      navigator.clipboard.writeText(text).then(options.done, function () {
        legacyCopy();
      });
    } else {
      legacyCopy();
    }

    function legacyCopy() {
      var elem = document.createElement('textarea');

      elem.value = text;
      elem.style.position = 'fixed';
      elem.style.opacity = '0';
      elem.style.top = '0px';
      elem.style.left = '0px';

      document.body.appendChild(elem);
      elem.select();

      try {
        document.execCommand('copy');
        typeof options.done === 'function' && options.done();
      } catch (err) {
        typeof options.error === 'function' && options.error(err);
      } finally {
        elem.remove ? elem.remove() : document.body.removeChild(elem);
      }
    }
  },
};

/**
 * 检测是否支持 Passive Event Listeners
 * 引用自 https://github.com/WICG/EventListenerOptions/blob/gh-pages/explainer.md
 * @type {boolean}
 */
lay.passiveSupported = (function () {
  var passiveSupported = false;
  try {
    var opts = Object.defineProperty({}, 'passive', {
      get: function () {
        passiveSupported = true;
        return passiveSupported;
      },
    });
    window.addEventListener('test', null, opts);
    window.removeEventListener('test', null, opts);
  } catch {
    // ignore
  }
  return passiveSupported;
})();

/**
 * 是否支持 touch 事件
 */
lay.touchEventsSupported = function () {
  return 'ontouchstart' in window;
};

var touchSwipeHandles = new WeakMap();
/**
 * @typedef touchSwipeState
 * @prop {{x: number,y: number}} pointerStart - 初始坐标
 * @prop {{x: number,y: number}} pointerEnd - 结束坐标
 * @prop {number} distanceX - X 轴移动距离
 * @prop {number} distanceY - Y 轴移动距离
 * @prop {'none'|'right'|'left'|'up'|'down'} direction - 滑动方向
 * @prop {Date} timeStart 开始时间
 */
/**
 * @callback touchSwipeCallback
 * @param {TouchEvent} e 滑动事件
 * @param {touchSwipeState} state 滑动相关的状态
 */
/**
 * 基于 touch 事件的触摸滑动
 * @param {string | HTMLElement | JQuery} elem - HTML 元素
 * @param {{onTouchStart?: touchSwipeCallback; onTouchMove?: touchSwipeCallback; onTouchEnd?: touchSwipeCallback; preventDefault?: boolean}} opts - 配置项
 * @returns {{dispose: () => void} | undefined}
 */
lay.touchSwipe = function (elem, opts) {
  var options = opts;
  var targetElem = getElement(elem);
  var preventDefault =
    'preventDefault' in options ? options.preventDefault : true;

  if (!targetElem || !lay.touchEventsSupported()) return;

  var state = {
    pointerStart: { x: 0, y: 0 },
    pointerEnd: { x: 0, y: 0 },
    distanceX: 0,
    distanceY: 0,
    direction: 'none', // 'up','down','left','right','none
    timeStart: null,
  };

  var onStart = function (e) {
    if (e.touches.length !== 1) return;
    bindEvents();
    // 重置状态
    state.timeStart = Date.now();
    state.pointerStart.x = state.pointerEnd.x = e.touches[0].clientX;
    state.pointerStart.y = state.pointerEnd.y = e.touches[0].clientY;
    state.distanceX = state.distanceY = 0;
    state.direction = 'none';

    options.onTouchStart && options.onTouchStart(e, state);
  };

  var onMove = function (e) {
    if (preventDefault) {
      e.preventDefault();
    }
    state.pointerEnd.x = e.touches[0].clientX;
    state.pointerEnd.y = e.touches[0].clientY;
    state.distanceX = state.pointerStart.x - state.pointerEnd.x;
    state.distanceY = state.pointerStart.y - state.pointerEnd.y;
    if (Math.abs(state.distanceX) > Math.abs(state.distanceY)) {
      state.direction = state.distanceX > 0 ? 'left' : 'right';
    } else {
      state.direction = state.distanceY > 0 ? 'up' : 'down';
    }
    options.onTouchMove && options.onTouchMove(e, state);
  };

  var onEnd = function (e) {
    options.onTouchEnd && options.onTouchEnd(e, state);
    unbindEvents();
  };

  var bindEvents = function () {
    targetElem.addEventListener(
      'touchmove',
      onMove,
      lay.passiveSupported ? { passive: false } : false,
    );
    targetElem.addEventListener('touchend', onEnd);
    targetElem.addEventListener('touchcancel', onEnd);
  };

  var unbindEvents = function () {
    // 移除事件时只对 capture 选项敏感
    targetElem.removeEventListener('touchmove', onMove);
    targetElem.removeEventListener('touchend', onEnd);
    targetElem.removeEventListener('touchcancel', onEnd);
  };

  if (touchSwipeHandles.has(targetElem)) {
    touchSwipeHandles.get(targetElem).dispose();
  }

  targetElem.addEventListener('touchstart', onStart);

  var handle = {
    dispose: function () {
      unbindEvents();
      targetElem.removeEventListener('touchstart', onStart);
      if (touchSwipeHandles.get(targetElem) === handle) {
        touchSwipeHandles.delete(targetElem);
      }
    },
  };
  touchSwipeHandles.set(targetElem, handle);
  return handle;
};

/** @type {(elem: Element|Document|Window,eventName: string,fn:EventListenerOrEventListenerObject,options: boolean | AddEventListenerOptions) => any}*/
lay.addEvent = function (elem, eventName, fn, options) {
  elem.addEventListener(eventName, fn, options);
};

/** @type {(elem: Element|Document|Window,eventName: string,fn:EventListenerOrEventListenerObject,options: boolean | EventListenerOptions) => any}*/
lay.removeEvent = function (elem, eventName, fn, options) {
  elem.removeEventListener(eventName, fn, options);
};

/**
 * 绑定指定元素外部的点击事件
 * @param {HTMLElement} target - 响应事件的元素
 * @param {(e: Event) => void} handler - 事件触发时执行的函数
 * @param {object} [options] - 选项
 * @param {string} [options.event="pointerdown"] - 事件类型
 * @param {HTMLElement | Window} [options.scope=document] - 事件范围
 * @param {Array<HTMLElement | string>} [options.ignore] - 忽略触发事件的元素或选择器字符串
 * @param {boolean} [options.capture=true] - 对内部事件 listener 使用捕获阶段
 * @param {boolean} [options.detectIframe] - 是否检测 iframe
 * @returns {() => void} - 返回一个停止事件响应的函数
 */
lay.onClickOutside = function (target, handler, options) {
  options = options || {};
  var eventType =
    options.event || ('onpointerdown' in window ? 'pointerdown' : 'mousedown');
  var scopeTarget = options.scope || document;
  var ignore = options.ignore || [];
  var useCapture = 'capture' in options ? options.capture : true;
  var detectIframe = options.detectIframe;

  var listener = function (event) {
    var el = target;
    var eventTarget = event.target;
    var eventPath = getEventPath(event);

    if (!el || el === eventTarget || eventPath.indexOf(el) !== -1) {
      return;
    }
    if (shouldIgnore(event, eventPath)) {
      return;
    }

    handler(event);
  };

  function shouldIgnore(event, eventPath) {
    var eventTarget = event.target;
    for (var i = 0; i < ignore.length; i++) {
      var target = ignore[i];
      if (typeof target === 'string') {
        var targetElements = document.querySelectorAll(target);
        for (var j = 0; j < targetElements.length; j++) {
          var targetEl = targetElements[j];
          if (targetEl === eventTarget || eventPath.indexOf(targetEl) !== -1) {
            return true;
          }
        }
      } else {
        if (
          target &&
          (target === eventTarget || eventPath.indexOf(target) !== -1)
        ) {
          return true;
        }
      }
    }
  }

  function getEventPath(event) {
    var path = (event.composedPath && event.composedPath()) || event.path;
    var eventTarget = event.target;

    if (path !== null && path !== undefined) {
      return path;
    }

    function getParents(node, memo) {
      memo = memo || [];
      var parentNode = node.parentNode;

      return parentNode
        ? getParents(parentNode, memo.concat([parentNode]))
        : memo;
    }

    return [eventTarget].concat(getParents(eventTarget));
  }

  function bindEventListener(elem, eventName, handler, opts) {
    elem.addEventListener(eventName, handler, opts);

    return function () {
      elem.removeEventListener(eventName, handler, opts);
    };
  }

  var cleanup = [
    bindEventListener(
      scopeTarget,
      eventType,
      listener,
      lay.passiveSupported
        ? { passive: true, capture: useCapture }
        : useCapture,
    ),
    detectIframe &&
      bindEventListener(window, 'blur', function (event) {
        setTimeout(function () {
          if (
            document.activeElement &&
            document.activeElement.tagName === 'IFRAME' &&
            target.contains &&
            !target.contains(document.activeElement)
          ) {
            handler(event);
          }
        }, 0);
      }),
  ];

  return function () {
    for (var i = 0; i < cleanup.length; i++) {
      cleanup[i] && cleanup[i]();
    }
    cleanup = null;
  };
};

/**
 * 检查对象是否具有指定的属性
 * @param {Record<string, any>} obj 要检查的对象
 * @param {string} prop 要检查的属性名
 * @returns {boolean} 如果对象具有指定的属性，则为 true；否则为 false
 */
lay.hasOwn = function (obj, prop) {
  return hasOwnProperty.call(obj, prop);
};

/**
 * 转义 HTML 字符串中的特殊字符
 * @param {string} html 要转义的 HTML 字符串
 * @returns {string} 转义后的 HTML 字符串
 */
lay.escape = function (html) {
  var exp = /[<"'>]|&(?=#?[a-zA-Z0-9]+)/g;
  if (html === undefined || html === null) return '';

  html += '';
  if (!exp.test(html)) return html;

  return html
    .replace(/&(?=#?[a-zA-Z0-9]+;?)/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/'/g, '&#39;')
    .replace(/"/g, '&quot;');
};

/**
 * 还原转义的 HTML 字符串中的特殊字符
 * @param {string} html 要还原转义的 HTML 字符串
 * @returns {string} 还原转义后的 HTML 字符串
 */
lay.unescape = function (html) {
  if (html === undefined || html === null) return '';

  return String(html)
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&gt;/g, '>')
    .replace(/&lt;/g, '<')
    .replace(/&amp;/g, '&');
};

/**
 * 将字符串编码为 base64
 * 在 btoa 的基础上，增加对 Unicode、编码模式的支持
 * @param {string} str - 待编码的二进制字符串
 * @param {'url'} [mode] - 编码模式，设为 `url` 时表示输出为 base64url 安全编码
 * @returns {string} 编码后的字符串
 * @see
 * - https://developer.mozilla.org/docs/Web/API/Window/btoa
 * - https://datatracker.ietf.org/doc/html/rfc4648#section-5
 */
lay.btoa = (str, mode) => {
  const bytes = new TextEncoder().encode(str);
  const chunkSize = 1024 * 32; // 用于对大字符串进行分块处理
  let binary = '';

  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
  }

  let encodedStr = btoa(binary);

  // 是否编码为 base64url
  if (mode === 'url') {
    return encodedStr
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=+$/, '');
  }

  return encodedStr;
};

/**
 * 生成唯一的 ID 字符串
 * @param {string} prefix ID 前缀，默认为'id'
 * @returns {string} 唯一 ID 字符串
 */
var generateUniqueId = (function () {
  var counter = 0;
  var lastTimestamp = null;

  return function (prefix) {
    prefix = prefix || 'id';
    var timestamp = new Date().getTime();

    // 如果时间戳与上一次相同，增加计数器
    // 否则重置计数器
    if (timestamp === lastTimestamp) {
      counter++;
    } else {
      counter = 0;
      lastTimestamp = timestamp;
    }

    // 结合时间戳、随机数和计数器生成 ID
    var random = Math.floor(Math.random() * 10000);

    return prefix + '-' + timestamp + '-' + random + '-' + counter;
  };
})();

/**
 * 创建共享的 ResizeObserver 实例
 * @param {string} namespace 命名空间，用于区分不同的 ResizeObserver 实例
 * @returns {ResizeObserver | null} ResizeObserver 实例或 null（如果不支持）
 */
lay.createSharedResizeObserver = function (namespace) {
  if (typeof window.ResizeObserver === 'undefined') {
    console.warn('ResizeObserver is not supported in this browser.');
    return null;
  }

  namespace = namespace || '';
  var ATTR_NAME = 'lay-' + namespace + '-resizeobserver-key';
  var handlerCache = {};

  var o = new ResizeObserver(function (entries) {
    for (var i = 0; i < entries.length; i++) {
      var attrValue = entries[i].target.getAttribute(ATTR_NAME);

      if (attrValue) {
        var callback = handlerCache[attrValue];
        if (typeof callback === 'function') {
          callback(entries[i]);
        }
      }
    }
  });

  return Object.freeze({
    observe: function (element, callback) {
      if (!element || !(element instanceof Element)) {
        console.warn('createSharedResizeObserver: Cannot observe non-Element.');
        return;
      }

      var attrValue = element.getAttribute(ATTR_NAME);
      if (!attrValue) {
        attrValue = generateUniqueId(namespace);
        element.setAttribute(ATTR_NAME, attrValue);
      }

      // 使用同一个观察者实例多次观察同一个元素，不会重复添加
      handlerCache[attrValue] = callback;
      o.observe(element);
    },
    unobserve: function (element) {
      if (!element || !(element instanceof Element)) {
        console.warn(
          'createSharedResizeObserver: Cannot unobserve non-Element.',
        );
        return;
      }

      var attrValue = element.getAttribute(ATTR_NAME);
      if (!attrValue) {
        return;
      }

      // 清除相关回调
      if (handlerCache[attrValue]) {
        delete handlerCache[attrValue];
      }

      element.removeAttribute(ATTR_NAME);
      o.unobserve(element);
    },
    disconnect: function () {
      for (var key in handlerCache) {
        if (lay.hasOwn(handlerCache, key)) {
          delete handlerCache[key];
          var elem = document.querySelector(
            '[' + ATTR_NAME + '="' + key + '"]',
          );
          if (elem) {
            elem.removeAttribute(ATTR_NAME);
          }
        }
      }
      o.disconnect();
    },
  });
};

/**
 * 树状数据转平铺
 * @param {Object[]} data - 树状数据
 * @param {Object} options - 可选项
 * @param {string} [options.childrenKey='children'] - 子节点字段名
 * @param {string} [options.idKey='id'] - 节点 id 字段名
 * @param {string} [options.parentKey='parentId'] - 父节点 id 字段名
 * @param {boolean} [options.keepChildren=true] - 是否保留子节点数据
 * @returns {Object[]} 返回平铺数据
 */
lay.treeToFlat = function (data, options) {
  options = Object.assign(
    {
      childrenKey: 'children',
      idKey: 'id',
      parentKey: 'parentId',
      keepChildren: true,
    },
    options,
  );

  // 展平
  var toFlat = function (initData, nodes, parentId) {
    return nodes.reduce(function (acc, currNode) {
      var children = currNode[options.childrenKey];

      if (!options.keepChildren) {
        delete currNode[options.childrenKey];
      }

      currNode[options.parentKey] = parentId; // 设置父节点 id
      acc.push(currNode);

      // 递归子节点
      if (children && children.length) {
        return toFlat(acc, children, currNode[options.idKey]);
      }

      return acc;
    }, initData);
  };

  return toFlat([], JSON.parse(JSON.stringify(data)), null);
};

/**
 * 平铺数据转树状
 * @param {Array} data - 平铺数据
 * @param {Object} options - 可选项
 * @param {string} [options.childrenKey='children'] - 子节点字段名
 * @param {string} [options.idKey='id'] - 节点 id 字段名
 * @param {string} [options.parentKey='parentId'] - 父节点 id 字段名
 * @param {boolean} [options.keepParentId=true] - 是否保留父节点 id 字段
 * @returns {Array} 返回树状数据
 */
lay.flatToTree = function (data, options) {
  options = Object.assign(
    {
      childrenKey: 'children',
      idKey: 'id',
      parentKey: 'parentId',
      keepParentId: true,
    },
    options,
  );

  data = JSON.parse(JSON.stringify(data)); // 深拷贝，防止修改原数据

  // 先创建节点映射，确保无论平铺数据的顺序如何，组装树时都能正确匹配
  var map = data.reduce(function (acc, currNode) {
    var id = currNode[options.idKey];
    acc[id] = currNode;
    // 给当前节点已有的 childrenKey 初始化为空数组
    if (options.childrenKey in currNode) {
      acc[id][options.childrenKey] = [];
    }
    return acc;
  }, {});

  // 组装树
  return data.reduce(function (acc, currNode) {
    var id = currNode[options.idKey];
    var parentId = currNode[options.parentKey];

    if (!options.keepParentId) {
      delete currNode[options.parentKey];
    }

    // 若为根节点，则直接添加到结果数组；
    if (parentId === null || !map[parentId]) {
      acc.push(map[id]);
    } else {
      // 若为子节点，则添加到对应父节点的 childrenKey 中
      var parentNode = map[parentId];

      // 若父节点的 childrenKey 不是数组，则初设一个空数组
      if (!Array.isArray(parentNode[options.childrenKey])) {
        parentNode[options.childrenKey] = [];
      }

      parentNode[options.childrenKey].push(currNode);
    }

    return acc;
  }, []);
};

export { lay, use, version };
